final class ShelfSearch(db: Database) {
  def locate(prefix: String): Future[Vector[String]] = {
    require(prefix.length <= 60)
    val pattern = prefix + "%"
    db.run(sql"SELECT title FROM books WHERE shelf LIKE '#$pattern' ORDER BY accession".as[String])
  }
}

